/** @type {Record<string, HTMLElement>} */
const iconTemplates = {};
for (const name in icons) {
  const $el = document.createElement('div');
  $el.classList.add('icon', `gui_icon_${name}`);
  $el.innerHTML = `<svg viewBox="0 0 17 17">${icons[name]}</svg>`;
  iconTemplates[name] = $el;
}

/**
 * @param  {string} name
 * @return {HTMLElement}
 */
export function createIcon(name) {
  let iconTemplate = iconTemplates[name];
  if (!iconTemplate) {
    console.warn('Invalid icon name ' + name);
    iconTemplate = iconTemplates['plus'];
  }
  return /** @type {HTMLElement} */(iconTemplate.cloneNode(true));
}
